function onEdit(e) {
  registrarCambios(e);
}
function registrarCambios(e) {
  var hojaRegistro = e.source.getSheetByName('Registro');
  var hojaEditada = e.range.getSheet().getName();

  if (hojaEditada == 'Registro') return; // Evita registrar cambios en la hoja de registro

  var direccion = e.range.getA1Notation();
  var valorNuevo = e.value;
  var valorViejo = e.oldValue || "";
  var fechaEdicion = new Date();
  var usuario = Session.getEffectiveUser().getEmail();


  hojaRegistro.appendRow([hojaEditada, direccion, valorViejo, valorNuevo, fechaEdicion, usuario]);
}

function onOpen() {
  const ui = SpreadsheetApp.getUi();
  ui.createMenu('Menú Personalizado')
    .addItem('Autorizar Script', 'authorizeScript')
    .addToUi();
}

function authorizeScript() {
  const user = Session.getActiveUser().getEmail();

  const ui = SpreadsheetApp.getUi();
  ui.alert('Autorización Exitosa', 'Has autorizado correctamente el script.', ui.ButtonSet.OK);
  console.info(`Authorization successful for user: ${user}`);
}

// ==============================================================================
// EMISOR Y CONTROLADOR MAESTRO DE DATOS: Code.gs
// Planilla de Origen: 1HKXGsRC149Kw4aBXQwGcPVpAvObvTUFis6YV6R5cTXk (Respuestas de formulario 4)
// Evento: Al enviar formulario (onFormSubmit)
// ==============================================================================

// Lista de Bases de Datos destino a sincronizar en simultáneo
const TARGET_SS_IDS = [
  "1aKptNgy8a9Ca3rDW-HSlWEiriMRJMOIJuFsdViwEGFc", // Database PRUEBAS
  "17yFPBMz8ExHf53e6ssh9LyDTjKCCJApoiCNXP-4KINQ"  // Database PRUEBAS LOCAL
];

function onNuevaOTFormulario(e) {
  if (!e || !e.range) return;

  const sourceSheet = e.range.getSheet();
  const rowNum = e.range.getRow();
  const rowData = sourceSheet.getRange(rowNum, 1, 1, sourceSheet.getLastColumn()).getValues()[0];

  const rawPlate = String(rowData[4] || '').toUpperCase().trim(); // Col E (Índice 4): Dom Tractor / Semi
  const newOt = String(rowData[8] || '').trim();                  // Col I (Índice 8): N° Orden

  if (!rawPlate || !newOt) return; 

  // Normalización y extracción de patentes (Mercosur: AA123BB / Tradicional: AAA123)
  const cleanPlateString = rawPlate.replace(/[\s\-_.]/g, '');
  const plateRegex = /([A-Z]{2}\d{3}[A-Z]{2}|[A-Z]{3}\d{3})/g;
  const matches = cleanPlateString.match(plateRegex);

  if (!matches || matches.length === 0) return; 

  // ============================================================================
  // PASO 1: ACTUALIZAR DB_OT_LIST EN AMBAS BASES DE DATOS
  // ============================================================================
  TARGET_SS_IDS.forEach(function(targetId) {
    try {
      const targetSS = SpreadsheetApp.openById(targetId);
      const targetSheet = targetSS.getSheetByName("DB_OT_LIST");
      if (!targetSheet) {
        console.warn("No se encontró la pestaña DB_OT_LIST en spreadsheet: " + targetId);
        return;
      }

      const dbData = targetSheet.getDataRange().getValues();
      let dbUpdated = false;

      // Recorrer filas de DB_OT_LIST (ignorar encabezado fila 1)
      for (let i = 1; i < dbData.length; i++) {
        const dbTractor = String(dbData[i][0] || '').toUpperCase().replace(/[\s\-_.]/g, ''); // Col A: UNIT_ID (Tractor)
        const dbSemi = String(dbData[i][2] || '').toUpperCase().replace(/[\s\-_.]/g, '');    // Col C: SEMI

        const isTractorMatch = matches.some(function(p) { return dbTractor && p === dbTractor; });
        const isSemiMatch = matches.some(function(p) { return dbSemi && p === dbSemi; });

        if (isTractorMatch || isSemiMatch) {
          if (isTractorMatch) {
            targetSheet.getRange(i + 1, 2).setValue(newOt); // Col B: OT Tractor
          }
          if (isSemiMatch) {
            targetSheet.getRange(i + 1, 4).setValue(newOt); // Col D: OT Semi
          }
          dbUpdated = true;
          break; // Poka-Yoke: detener de inmediato para evitar duplicaciones
        }
      }

      // Poka-Yoke: Si no pertenece a la flota canónica activa, NO usar appendRow para no corromper la tabla
      if (!dbUpdated) {
        console.warn("Patente " + rawPlate + " no pertenece a la flota canónica en " + targetId + ". Inserción omitida para proteger DB_OT_LIST.");
      }
    } catch (errDb) {
      console.error("Error al actualizar DB_OT_LIST en " + targetId + ":", errDb);
    }
  });

  // ============================================================================
  // PASO 2: NOTIFICACIÓN EN TIEMPO REAL A RENDER (WEBSOCKET + TABLA OTS)
  // ============================================================================
  try {
    const payload = {
      dirtyPlate: rawPlate,
      otNumber: newOt,
      sectorTareas: String(rowData[5] || ''),
      cierreRespaldo: String(rowData[6] || ''),
      fecha: String(rowData[2] || ''),
      confirmacion: String(rowData[7] || '')
    };

    const options = {
      method: "post",
      contentType: "application/json",
      payload: JSON.stringify(payload),
      muteHttpExceptions: true
    };

    UrlFetchApp.fetch("https://panolnd.onrender.com/webhook/nueva-ot", options);
  } catch (errWebhook) {
    console.error("Error al notificar webhook en Render:", errWebhook);
  }
}
